from lib import *
S = SS('n36')
steps = [
    step("NegotiateFormat 的实现:parseAccept 把 Accept 按逗号拆开、分号后面的参数(q 值)全部丢掉;然后按 Accept 里出现的顺序,对每个 Offered 做逐字符前缀比较(遇到 * 就算匹配,Accept 比 Offered 短也算匹配);Accept 为空返回第一个 Offered;没有任何匹配返回空串。注意:不看 q 值、不区分优先级、区分大小写。", t=tl(S(1)), mark=lidx(S(1), 'part = part[:i]', 'if accepted[i] == \'*\' || offer[i] == \'*\'', 'return offered[0]'), done=lidx(S(1), 'parseAccept(c.requestHeader("Accept"))', 'if i == len(accepted)'), kv=KV([['q 值', '直接丢弃'], ['顺序', 'Accept 里出现的顺序决定,不是 q 值'], ['比较', '逐字符前缀,区分大小写']], ['q 值'])),
    step("NegotiateFormat(JSON, XML, HTML) 对不同 Accept 的结果:没有 Accept 或为空 → 第一个 Offered(application/json);text/html,application/xml;q=0.9,*/*;q=0.8(浏览器式)→ text/html;text/html;q=0.1, application/json;q=0.9 → 仍是 text/html(q 被忽略);application/json;q=0, text/html → application/json(客户端说“不要 json”也选了它);*/* 与 application/* → application/json;text/* → text/html;image/png → \"\";image/png, */* → application/json;TEXT/HTML(大写)→ \"\";application/vnd.api+json → \"\"。", t=tl(S(2)), mark=lidx(S(2), 'text/html;q=0.1, application/json;q=0.9', 'application/json;q=0, text/html', '"TEXT/HTML"', 'application/vnd.api+json', '"image/png"  '), done=lidx(S(2), '"text/html,application/xml;q=0.9,*/*;q=0.8"', '"*/*"', '"text/*"'), kv=KV([['q 值', '被忽略(q=0 也会被选中)'], ['通配符', '*/* 选第一个 Offered'], ['大小写', '区分,TEXT/HTML 匹配不上']], ['q 值'])),
    step("c.Negotiate 按选出的格式渲染:Accept: application/json → JSON(Content-Type: application/json; charset=utf-8);application/xml → XML;application/x-yaml → YAML(Content-Type 是 application/yaml);Accept: application/yaml 却是 406 ——Offered 里写的是 application/x-yaml,字符串前缀对不上;text/html 没提供 → 406;text/html,application/xml → 跳过 html,选 xml;没有 Accept 或 */* → 第一个。Data 是通用数据,JSONData 等是针对某种格式的专用数据(/data 里 JSON 取 JSONData,XML 取 Data)。", t=tl(S(3)), mark=lidx(S(3), '"application/yaml"', '"text/html"  ', '/data Accept'), done=lidx(S(3), '"application/json"', '"application/xml"', '"application/x-yaml"', '"*/*"'), kv=KV([['无匹配', '406'], ['application/yaml', '提供 x-yaml 时匹配不上 → 406'], ['JSONData 等', '覆盖通用的 Data']], ['application/yaml'])),
    step("406 的细节:没有匹配时 Negotiate 的 default 分支调用 AbortWithError(406, errors.New(“the accepted formats are not offered by the server”)):响应状态 406、没有正文、没有 Content-Type,错误同时进了 c.Errors,但之前设置的头 X-Before 仍在;同一个请求里 NegotiateFormat 调两次用同一份已解析的 c.Accepted(缓存),第二次换一组 Offered 也能选出 application/xml;不传任何 Offered 会 panic:you must provide at least one offer。", t=tl(S(4)), mark=lidx(S(4), '状态 406', 'c.AbortWithError(http.StatusNotAcceptable'), done=lidx(S(4), '第一次 ""', 'panic: you must provide at least one offer'), kv=KV([['无匹配', 'AbortWithError(406),错误进 c.Errors'], ['c.Accepted', '一个请求内缓存'], ['空 Offered', 'panic']], ['无匹配'])),
]
A = mkartn('n36', 36, 'Gin,内容协商,Negotiate,Accept,406,Go,真实验证,动画演示',
    '在 Gin v1.12.0 里实测内容协商:NegotiateFormat 丢弃 q 值,按 Accept 里的出现顺序逐字符前缀匹配(区分大小写),所以 application/json;q=0 仍会被选中;application/yaml 对不上 application/x-yaml 会 406;没有匹配时 Negotiate 返回 406 并把错误记入 c.Errors;不传 Offered 会 panic。',
    'Accept 头里有 q 值、通配符、大小写不一样,Gin 的 Negotiate 到底怎么选?这篇从 NegotiateFormat 的 20 行源码出发,用 16 种 Accept 头把它的真实行为列出来,看它与 RFC 的差别和使用时的坑。',
    [('q=0 仍选中', 'Accept: application/json;q=0, text/html 选出的是 application/json'), ('406', 'Offered 写 application/x-yaml 时,Accept: application/yaml 匹配不上'), ('TEXT/HTML → 空', 'Accept 大小写不一致就匹配不上任何 Offered')],
    [('实现只有二十行', '<p>Gin 先把 <code>Accept</code> 按逗号拆开,把每一项分号后面的参数(包括 <code>q=</code>)整体丢掉,然后按<b>出现顺序</b>逐项去匹配 Offered,逐字符比较前缀,遇到 <code>*</code> 就算命中。所以它不是 RFC 7231 意义上的“按质量值协商”,而是“按 Accept 书写顺序的首个匹配”。</p>'),
     ('16 种 Accept 头', '<p>浏览器式的 <code>text/html,application/xml;q=0.9,*/*;q=0.8</code> 选 HTML;<code>text/html;q=0.1, application/json;q=0.9</code> 仍选 HTML(客户端其实更想要 JSON);<code>application/json;q=0, text/html</code> 选了客户端明确拒绝的 JSON。通配符 <code>*/*</code> 选第一个 Offered,所以 Offered 的第一个应该放最通用的格式。<code>TEXT/HTML</code> 大写、<code>application/vnd.api+json</code> 这样的子类型后缀都匹配不上。</p>'),
     ('Negotiate 渲染', '<p><code>c.Negotiate</code> 用选出的格式去调用对应的渲染方法。<code>Data</code> 是通用数据,<code>JSONData</code>、<code>XMLData</code> 等可以给个别格式提供不同的数据。有一个容易踩的坑:YAML 的两个 MIME(<code>application/x-yaml</code> 与 <code>application/yaml</code>)只有你写进 Offered 的那个能匹配上,而渲染出的 Content-Type 总是 <code>application/yaml</code>。</p>'),
     ('406 与边界', '<p>没有任何格式匹配时,<code>Negotiate</code> 调用 <code>AbortWithError(406, …)</code>,错误信息是 “the accepted formats are not offered by the server”,同时记入 <code>c.Errors</code>;响应没有正文和 Content-Type。<code>NegotiateFormat</code> 自己只返回空串,由你决定怎么处理。Accept 在一个请求内只解析一次(缓存在 <code>c.Accepted</code>)。</p>')],
    steps,
    [ENV_N_GIN + '。请求用 httptest 直接调用 ServeHTTP,Accept 头逐个设置;每种情形各一次',
     '没有验证:HTML 格式的 Negotiate(需要模板,见模板一篇);XML / YAML 在带类型的结构体上的输出细节(只试了一个简单结构体);与 RFC 7231 的完整对照(只列出了差别);浏览器在真实请求里发送的 Accept 头(这里用的是手写的典型值);Protobuf、BSON、TOML 格式的协商'],
    '内容协商')
